// Simplified orchestrator logic:
while (!conversationComplete) {
  var userInput = await UI.GetInput();
  var llmResponse = await LLM.SendPrompt(userInput, history);

  if (llmResponse.HasToolCalls) {
    var toolResults = await ToolSystem.Execute(llmResponse.ToolCalls);
    llmResponse = await LLM.SendToolResults(toolResults);
  }

  await UI.DisplayResponse(llmResponse);
  history.Add(userInput, llmResponse);
}
